<script setup lang="ts">import{onMounted,ref}from'vue';import{interviewApi}from'../api/modules';const list=ref<any[]>([]),loading=ref(true),error=ref('');async function load(){loading.value=true;try{list.value=await interviewApi.history()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}onMounted(load)</script>
<template><section class="page-head"><div><h2>面试记录</h2><p>数据来自 MySQL 中的真实面试会话。</p></div></section><div v-if="loading" class="state-card">加载中</div><div v-else-if="error" class="state-card error">{{error}} <button @click="load">重试</button></div><div v-else-if="!list.length" class="state-card">还没有面试记录。</div><section v-else class="panel data-list"><div v-for="s in list" :key="s.id" class="list-row"><span><b>{{s.targetRole}}</b><small>{{s.startedAt}} · {{s.currentQuestion}} 道已完成</small></span><span class="tag" :class="s.status==='COMPLETED'?'green':'orange'">{{s.status}}</span><router-link :to="s.status==='COMPLETED'?`/report/${s.id}`:`/interview/${s.id}`">{{s.status==='COMPLETED'?'查看报告':'恢复面试'}}</router-link></div></section></template>
